  return {name,operator,runtime,database,authorities,users,companyId,otherCompanyId,migrationSha256:manifest.at(-1)!.sha256,close:async()=>{await runtime!.close();await operator!.close()}}
 }catch(error){await runtime?.close();await operator?.close();throw error}finally{await source.close();await admin.close()}
}
